<main class="scroll-wall <?php if (($view['site']['skin_presentation']['options']['scroll_wall_layout'] ?? '') === 'square'): ?>ss-square-wall<?php else: ?>ss-masonry<?php endif; ?>" data-wall-layout="<?php echo snap_escape_attr($view['site']['skin_presentation']['options']['scroll_wall_layout'] ?? ''); ?>" data-mosaic-emphasis="<?php echo snap_escape_attr($view['site']['skin_presentation']['scroll']['mosaic_emphasis'] ?? ''); ?>"><?php foreach (($view['response']['items'] ?? []) as $item): ?><a class="ss-masonry-item scroll-feature-item" href="<?php echo snap_escape_url($item['url'] ?? snap_route_url('photo',['slug'=>$item['img_slug'] ?? ''])); ?>" aria-label="<?php echo snap_escape_attr($item['img_title'] ?? 'View photograph'); ?>"><?php if (!empty($item['img_thumb_aspect']) || !empty($item['img_file'])): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$item['img_thumb_aspect'] ?? $item['img_file'],'alt'=>$item['img_alt'] ?? $item['img_title'] ?? '','class'=>'scroll-image'])); ?><?php endif; ?><span class="scroll-item-title"><?php echo snap_escape_html($item['img_title'] ?? ''); ?></span></a><?php endforeach; ?><?php if (empty($view['response']['items'])): ?><p class="scroll-empty">No photographs yet.</p><?php endif; ?></main>
<?php elseif (($view['response']['kind'] ?? '') === 'photo' || ($view['response']['kind'] ?? '') === 'post' || ($view['response']['kind'] ?? '') === 'collection'): ?><header class="scroll-solo-header"><div class="scroll-solo-header-inside"><a class="scroll-solo-title" href="<?php echo snap_route_url('home'); ?>"><?php echo snap_escape_html($view['site']['site_name']); ?></a><nav class="scroll-solo-nav"><?php echo snap_render_html(snap_render_component('navigation',['items'=>$view['response']['navigation'] ?? []])); ?></nav></div></header><main class="scroll-solo-stage h-entry"><h1 class="scroll-horizontal-title p-name"><?php echo snap_escape_html($view['response']['item']['img_title'] ?? $view['response']['item']['title'] ?? ''); ?></h1><div class="scroll-solo-photobox scroll-photo-wrap"><?php if (!empty($view['response']['item']['img_file']) || !empty($view['response']['item']['featured_image_path'])): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$view['response']['item']['img_file'] ?? $view['response']['item']['featured_image_path'],'alt'=>$view['response']['item']['img_alt'] ?? $view['response']['item']['img_title'] ?? '','class'=>'scroll-image post-image u-photo'])); ?><?php endif; ?></div><div class="scroll-infobox e-content"><?php echo snap_render_html($view['response']['item']['content'] ?? $view['response']['item']['description'] ?? $view['response']['item']['img_description'] ?? ''); ?></div><?php if (!empty($view['response']['comments'])): ?><?php echo snap_render_html(snap_render_component('comments',['items'=>$view['response']['comments']])); ?><?php endif; ?></main>
<?php elseif (($view['response']['kind'] ?? '') === 'page'): ?><header class="scroll-page-header"><a class="scroll-horizontal-title" href="<?php echo snap_route_url('home'); ?>"><?php echo snap_escape_html($view['site']['site_name']); ?></a></header><main class="scroll-static-content"><div class="scroll-static-inner"><h1 class="static-page-title"><?php echo snap_escape_html($view['response']['item']['title'] ?? ''); ?></h1><div class="description"><?php echo snap_render_html($view['response']['item']['content'] ?? ''); ?></div></div></main>
<?php else: ?><main class="scroll-empty"><h1>Not found</h1></main><?php endif; ?>
